    /// <summary>
    /// Handles a push notification. Returns error with code 406 if the push notification is not supported and connection to the server is required to fetch new data. Can be called before authorization
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> ProcessPushNotificationAsync(string payload = default)
    {

           using var activity =  StartCallActivity("ProcessPushNotificationAsync", typeof(ProcessPushNotification).FullName ?? "ProcessPushNotificationAsync");

           try
           {
             return client.ProcessPushNotificationAsync(payload);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
